SFCM_DATA_PART("audits/recs/recs.json",5,183,{"rows":{"rows":[["K-f386e784c1",73,"cgj","BOS",5,5,null,"The Board of Supervisors should study the Municipal Code structure, especially with respect to (a) labeling of report requirements, and (b) how the indexes are established. Report requirements should be better identified.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7a",11,3,null,"Municipal Code requirements sometimes are not easy to find; indexes are deficient and report requirements are not well labeled.",5,11,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-56761bd547",73,"cgj","BOS",5,11,null,"As the Board is currently doing with its revisions to the Administrative Code, consideration should be given to revising other parts of the Municipal Codes. The Board should review current report requirements for relevance, and consider elimination of those requirements no longer useful.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7b",11,3,null,"Some Municipal Code report requirements may have outlived their usefulness but remain in effect.",10,0,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-4dde947189",73,"cgj","CAT",5,5,null,"In its role to prepare and make available a codification of the ordinances of the City and County (Charter Section 6.102), the City Attorney's Office should consider preparing a master index for all Sections of the Charter and Municipal Codes. A master index would make it easier for agencies to identify all requirements that apply to them.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7c",11,3,null,"Municipal Code requirements are sometimes hard to find, and responsibilities for reports are called out in unexpected code sections.",5,8,null,null,null,null,null,7,null,null,null,null,null,3,["City Attorney"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-38c1d1fdc4",73,"cgj","BOS",5,5,null,"On a regular basis (perhaps yearly), the Clerk of the Board of Supervisors should send out a reminder letter to all agencies regarding the need to send, through the Office of the Clerk, any documents required to be reported to the Board of Supervisors.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"8",12,3,null,"Some agencies send reports directly to individual Supervisors rather than through the Clerk, so material is not logged or available for public review at the Clerk's Office.",5,0,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-04377b3487",73,"cgj","BOS",5,0,null,"Administrative Code, Section 1.56, should be revised to allow either the Annual Report or Annual Statement of Purpose option.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9a",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-98a47f8f1f",73,"cgj","BOS",5,0,null,"Section 1.56 should be revised to note that the Annual Statement of Purpose and the Mission and Goals statements are equivalent.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9b",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-e414d55ddc",73,"cgj","BOS",5,0,null,"Section 1.56 should be revised to clarify which boards and commissions (all, just those in charter, none that are advisory, etc.) to which it applies.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9c",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-3437f35f67",73,"cgj","BOS",5,0,null,"Sections 1.56 and 2A.30 should be revised to indicate to whom the Annual Report should be sent.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9d",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-5b8bf5e057",73,"cgj","BOS",5,0,null,"Sections 1.56 and 2A.30 should be revised to indicate Annual Report expectations for those cases where there is both a department and a board or commission (two separate Annual Reports would not be required).",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9e",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-1b14fdc66c",73,"cgj","BOS",5,0,null,"Consideration should be given to some form of combination of the Annual Report and Customer Service Plan report requirements. Some examples of Annual Reports with specific content requirements include Park and Recreation and the Lead Hazard Reduction Program.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9f",12,3,null,"Municipal Code Annual Report and Annual Statement of Purpose requirements are not well defined.",1,11,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-6d3e59bda3",73,"cgj","BOS",5,5,null,"We recommend that the Task Force review this report for concurrence and followup. For those recommendations with which the Task Force agrees, we request that the Task Force consider sending letters of concurrence to those from whom we have required a response, notifying them of your concurrence.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"10",13,3,null,"Some of the findings in this report may be of interest to the Sunshine Task Force.",5,null,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.85,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-2ed0dd28ad",73,"cgj","MYR",5,5,null,"A reminder regarding City policy on posting information on the Internet should be developed and communicated to all affected agencies.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"11",14,3,null,"Several agencies are placing documents on their Internet web pages, but Section 8.16 does not specify this as a method of compliance, and there are concerns about currency, access, and document control.",5,8,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office"],null,null,null,null,{"text":0.9,"department":0.85,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-ea275981c4",73,"cgj","BOS",5,5,null,"We recommend that the Task Force discuss Table 2 and the issue of web pages at one of their public meetings.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"12",14,3,14,"Several agencies did not have a web page; recent Sunshine ordinance changes include direction regarding Internet posting.",5,8,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.85,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-0d7ef624c5",68,"cgj","NONCITY",5,5,null,"Future administrations of SFUSD would do well to follow the example of the current acting SFUSD administration in cooperating fully with any investigations conducted by the San Francisco Civil Grand Jury pertaining to SFUSD.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1",5,3,null,"Prior administration was perceived to obstruct and delay the 1998-1999 Civil Grand Jury's investigation into Proposition 227 implementation.",5,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-df253fc428",68,"cgj","NONCITY",5,14,null,"It would greatly improve the public's understanding of SFUSD and bilingual education in general if more was done in terms of informing the public as to the waiver allowance as well as the pedagogical value SFUSD perceives in the Dual Language Educational model. SFUSD should explore the various public relation avenues in this regard.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"2",5,3,null,"Public misunderstanding exists regarding parental waivers under Proposition 227 and the value of the Dual Language Education model used by SFUSD.",13,10,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.6,"response":0.9,"target_date":0.95},null,[]],["K-dcc3488715",68,"cgj","CAT",5,2,null,"The City Attorney should direct all attorneys employed by her office that there should be no communication between them and the counsel representing the Civil Grand Jury on any substantive matter including the time or date of any particular interview. Finally, the incoming Civil Grand Jury should be particularly vigilant in this area realizing that any indiscretions on the part of counsel are...",662,"none",null,5,null,null,null,671,0.6,null,{"score":4,"why":"Repeats an earlier recommendation to the same department; public safety/health or ethics topic."},"3",5,3,null,"Ambiguity and potential conflict of interest exists regarding the City Attorney's Office acting as counsel both for the Civil Grand Jury and for departments under investigation.",3,5,null,null,null,null,null,7,null,null,null,null,null,3,["City Attorney"],null,null,36,"C-0632",{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-c15db32849",63,"cgj","MYR",5,11,null,"CARC should be continued after the pilot program period. A meeting should be set as soon as possible after the NCCD evaluation. This meeting should give all interested parties an opportunity to be heard on issues that will be addressed in the NCCD evaluation and raised in this CGJ investigation.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1",6,3,null,"CARC was criticized as underutilized based on an earlier study, but the Grand Jury found it improving and valuable as a pilot project nearing completion.",10,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Juvenile Probation"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-90f25d587c",63,"cgj","BOS",5,5,null,"In light of the fact that despite the drop in juvenile crime and the success of CARC there continues to be a high number of juveniles detained at YGC, we would recommend that the Board of Supervisors obtain copies of the population management investigation of both the Implementation Team and the Probation Department and schedule a hearing as to why there has not been a decrease in the number...",413,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"2",7,3,null,"Despite falling juvenile crime rates since 1988, the daily population at Juvenile Hall (YGC) has not decreased.",5,10,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors","Juvenile Probation"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-91503622bc",63,"cgj","MYR",5,5,null,"If CARC is continued after the NCCD evaluation, the issue of the type of cases that should be referred to CARC should be made clear. While the decision of the exception of juveniles from who are referred to CARC may be that of the CBC, it is recommended that leadership be taken either by the Implementation Team or the Coordinating Council of the Mayor's Criminal Justice Council in order to...",381,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",7,3,null,"There is ambiguity and lack of clear criteria regarding which juvenile offenders are referred to CARC versus Youth Guidance Center, especially high-risk youth.",5,11,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Juvenile Probation","Police Department","District Attorney","Public Defender","Public Health"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.65,"response":0.9,"target_date":0.95},null,[]],["K-81f45473a5",63,"cgj","MYR",5,5,null,"A meeting should be set as soon as possible after the NCCD evaluation before either the Implementation Team or the Mayor's Criminal Justice Council. Consideration should be given to soliciting help from the signatories of the Action Plan as well as San Francisco State University and Golden Gate University. This meeting should give all interested parties an opportunity to be heard on issues...",2,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"4",7,3,null,"There is no proper public forum to present the NCCD evaluation results and ensure dialogue with and input from the public and stakeholders.",5,11,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Juvenile Probation"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.65,"response":0.9,"target_date":0.95},null,[]],["K-5292b74a80",63,"cgj","MYR",5,5,null,"The Implementation Team should agree to meet on a regular basis, at least twice a year, to discuss significant issues related to the Action Plan.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"5",8,3,null,"There is no formalized method or regular meeting schedule for Action Plan signatories to update, amend, or reach consensus on significant issues.",5,11,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Juvenile Probation"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.6},null,[]],["K-ceee4a77d0",65,"cgj","ADM",5,14,null,"If representatives of the Investigation Team are going to be delayed and cannot arrive at the scene of a death within one hour of advising the parties of the scheduled arrival, the investigators should telephone the individuals at the scene, explain the delay and give an approximate time of arrival. The investigator's ambulance should contain a cell phone.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1",16,3,null,"Family members were sometimes not notified when investigators were delayed in arriving at death scenes, causing distress.",13,null,null,null,null,null,null,7,null,null,null,null,null,3,["City Administrator"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-b2a4065e63",65,"cgj","ADM",5,14,null,"A master list of crime-scene cleaning services should be prepared by the MEO and made available on request to individuals requiring help in cleaning up a premises that has been the scene of a violent crime.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"2",17,3,null,"MEO declined to provide referrals for crime-scene cleaning services, leaving victims' families without guidance beyond checking the phone book.",13,null,null,null,null,null,null,7,null,null,null,null,null,3,["City Administrator"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-31330f6f21",65,"cgj","ADM",5,14,null,"Brochures currently available at the MEO in the Hall of Justice explaining the duties and functions of the MEO in several languages should also be available in the investigator's ambulances so that it may be distributed to the survivors or friends of the deceased at the time the investigators visit the scene.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",17,3,null,"Informational brochures about MEO functions were only available at the office, not carried by investigators to distribute to grieving families at the scene.",13,null,null,null,null,null,null,7,null,null,null,null,null,3,["City Administrator"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-b55e607014",65,"cgj","ADM",5,3,null,"The door to the autopsy room used by ambulances and investigator vehicles is the original door constructed at the time the Hall of Justice was built and is marginally secure. Considering the potential liability of the City should a break-in occur, a requisition should be made for the replacement to a door with appropriate standards for security.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"4",17,3,null,"The original Hall of Justice door used for autopsy room access is insecure and could be forced open, risking unauthorized access to remains and City liability.",0,13,null,null,null,null,null,7,null,null,null,null,null,3,["City Administrator","Public Works"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-2b7a36e95d",65,"cgj","ADM",5,5,null,"The present Chief Medical Examiner is a dedicated public servant highly respected in the Forensic Pathology community, as well as with City departments, agencies, and the judiciary. Budgetary constraints currently require his active participation in virtually all aspects of MEO activity. The Chief Medical Examiner will not be with us forever. Appropriate planning and discussion must be...",884,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"5",17,3,null,"No succession or contingency planning exists for the eventual retirement, illness, or departure of the current Chief Medical Examiner, who fills multiple critical roles.",5,7,null,null,null,null,null,7,null,null,null,null,null,3,["City Administrator","Human Resources"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-63bc80aed5",64,"cgj","NONCITY",5,11,null,"The SFUSD should carry out research identifying other large urban districts which are similarly underfunded for Special Education staffing and resources.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1A",7,3,null,"SFUSD has a disproportionately higher percentage of students identified for Special Education than state funding estimates account for.",10,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-85a5f7b886",64,"cgj","NONCITY",5,11,null,"The SFUSD should carry out research identifying other large urban districts similarly underfunded for Special Education to develop common strategies in order to lobby the California Department of Education and the state legislature for changes of the Special Education Formula so that funding is done based on the actual enrollment rather than rigid estimated levels.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1B",7,3,null,"SFUSD has a disproportionately higher percentage of students identified for Special Education than state funding estimates account for.",10,9,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-9743e26145",64,"cgj","NONCITY",5,11,null,"Since early intervention can provide better education for a child with special needs and potentially save resources over time by avoiding multiple remedial interventions, the SFUSD should consider lobbying both the California Department of Education and the state legislature to directly fund pre-school programs which can lead to early identification of a child's special education needs. As an...",610,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"2",7,3,null,"SFUSD General Fund pays for some pre-school programs that could lead to early identification of special education needs, but lacks direct state funding for these.",10,9,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-c6c9294b5f",64,"cgj","NONCITY",5,1,null,"The SFUSD should reduce the number of consultants. These funds should then be re-allocated to pay Special Education teachers for the additional work necessary.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",8,3,null,"Special Education teachers must spend significant time outside classroom instruction to complete lengthy IEPs, while SFUSD pays numerous consultants excessive amounts.",2,7,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-05f4bc9879",64,"cgj","NONCITY",5,7,null,"There must be an increase in the salary of both teachers and psychologists. The SFUSD must allocate sufficient funding for the salaries of both teachers and psychologists. Special action by the SFUSD is needed in order to budget for Special Education teachers based on the number of Special Education students in San Francisco schools as opposed to estimates based on a statewide average.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"4",8,3,null,"Failure to provide regionally competitive salaries for Special Education teachers and psychologists contributes to non-compliance with State and Federal regulations.",14,4,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-a6789b80f9",64,"cgj","NONCITY",5,7,null,"Priority must be given to the hiring of substitute teachers with full Special Education credentials rather than emergency credentials. A bonus or some other means of incentive should be instituted for substitute teachers who enroll in courses toward their Special Education credential.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"5",8,3,null,"Failure to provide substitute teachers with adequate special education training contributes to non-compliance with state and federal regulations.",14,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-855e60a32c",64,"cgj","NONCITY",5,7,null,"There should be a bonus or some other means of incentive for teachers to stay with the SFUSD.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"6",9,3,null,"Failure to provide bonuses or differential pay to Special Education teachers, or extra pay for the extra work involved in completing each IEP, contributes to difficulties in hiring qualified Special Education teachers.",14,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-bc9d7b2e52",64,"cgj","NONCITY",5,7,null,"The SFUSD should fund additional administrative support staff for the principals.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7",9,3,null,"Additional work is required by school principals for monitoring and updating IEP evaluations, and principals need administrative support staff for the additional time needed.",14,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-4ffb2a6c3d",64,"cgj","NONCITY",5,8,null,"The Corrective Action data system must include the tracking of delays in psychological testing as well as other timelines. The data gathered must reflect whether the delay is due to lack of parental consent or delay in scheduling the psychological examination.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"8",9,3,null,"The VCAP data system fails to track the reason for delay of psychological assessments (lack of parental signature vs. scheduling delay).",7,null,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-deb6f8fb7f",64,"cgj","NONCITY",5,4,"high","The highest priority must be given to budgeting for essential teaching materials and supplies. It is inexcusable that teachers must pay for these necessities out of their own pocket.",null,"none",null,5,null,null,null,null,null,null,{"score":4,"why":null},"9",9,3,null,"Teachers are paying for some classroom teaching materials and supplies out of their own pocket.",4,14,29,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.6,"response":0.9,"target_date":0.95},null,[]],["K-2b4a43af63",64,"cgj","NONCITY",5,10,null,"The VCAP data system must be programmed so that there is a quarterly compilation of all the data, with names redacted. This information should be made available to the public.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"10",10,3,null,"Information and reports generated from the data-tracking system are not being made available to principals, teachers, families or the general public.",9,8,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-ffce064500",64,"cgj","NONCITY",5,0,null,"The Corrective Action data system must include adequate monitoring of the schools in order to ensure privacy of the files of Special Education students. The public should be made aware of the process by which privacy is ensured.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"11",10,3,null,"There is an inadequate system to monitor the files of Special Education students to ensure privacy.",1,8,null,null,null,null,null,7,null,null,null,null,null,3,["School District"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-6b9db189b3",69,"cgj","SHF",5,13,null,"The ventilation problem at County Jails #1 and #2 should be corrected or at least alleviated in some way. The Sheriff's Department should look into short-term and long-term solutions to improve the ventilation in these facilities.",null,"none",null,5,null,null,null,null,null,null,{"score":3,"why":null},"1",2,3,null,"Poor ventilation in kitchen and laundry areas at County Jails #1 and #2 causes discomfort and contributes to tension among inmates and staff.",12,3,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-ea95026f69",69,"cgj","SHF",5,13,null,"In the interests of inmate safety and hygiene, the showers should be repaired and the ventilation should be improved in all of the cell blocks in County Jail #3.",null,"none",null,5,null,null,null,null,null,null,{"score":3,"why":null},"2",3,3,null,"Showers at County Jail #3 are in disrepair with leaking floors, broken tiles, and dirty shower curtains, and the jail has ventilation problems.",12,3,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-58faae2107",69,"cgj","SHF",5,5,null,"A review of the work order system should be conducted to streamline the process for getting small repairs taken care of in the jail.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",3,3,null,"The work order system for repairs at County Jail #3 is inefficient, with minor problems taking days or weeks to be fixed due to routing through multiple supervisors.",5,3,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-c970d44088",69,"cgj","SHF",5,14,null,"All inmates should be allotted more \"yard time,\" provided that security and other staffing concerns are addressed.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"4",3,3,null,"Inmates at County Jail #3 receive only the court-mandated minimum three hours of weekly exercise time, and vulnerable inmates in administrative segregation often receive even less.",13,13,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-fee208520d",69,"cgj","SHF",5,13,null,"The retrofitting of the TB isolation cells should be undertaken as soon as possible and a plan for addressing the future needs of Jail Medical Services in holding and treating infectious inmates should be prepared.",null,"none",null,5,null,null,null,null,null,null,{"score":3,"why":null},"5",3,3,null,"TB isolation cells at County Jail #8 reportedly do not meet health and safety requirements for air turnover and pressure, risking spread of infection.",12,3,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-0b8f3c16f4",69,"cgj","SHF",5,14,null,"A plan to reduce the overcrowding in the women's section of County Jail #9 and to address the future needs for housing a growing population of female inmates should be prepared by the Sheriff's Department.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"6",4,3,null,"The women's section of County Jail #9 is overcrowded, forcing several women inmates to sleep on the floor due to insufficient beds.",13,3,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-52375d5160",69,"cgj","SHF",5,14,null,"The Sheriff's Department should also investigate the causes (e.g., mental illness, jail conditions) which lead to the disruptive and aggressive behavior of female inmates and implement a harm-reduction policy to better protect inmates and staff from problem inmates.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7",4,3,null,"Deputies reported that female inmates exhibit more disruptive and aggressive behavior, which may be exacerbated by overcrowded conditions.",13,13,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.85,"department":0.95,"category":0.65,"response":0.9,"target_date":0.95},null,[]],["K-ffc45dc319",69,"cgj","SHF",5,5,null,"The process by which inmates are selected to participate in the rehabilitation programs should be reviewed to eliminate the possibility that an inmate may be unfairly denied participation in or removed from a program without proper justification.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"8",4,3,null,"Inmates alleged that deputies and program staff could penalize certain inmates, such as homosexual, transgender, or grievance-filing inmates, by denying them program participation without proper justification.",5,14,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.85,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-e6bf5cc7ca",69,"cgj","SHF",5,14,null,"Reasonable accommodations should be made to allow vulnerable inmates to participate in the programs.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9",5,0,null,"Vulnerable inmates separated from the main population cannot mingle with others in County Jail #7's pod housing, preventing them from participating in rehabilitation programs.",13,null,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.85,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-5afa36d2c4",69,"cgj","SHF",5,5,null,"The Sheriff's Department should publicly report on the basis of the high cost of calls made through the jail telephone system and the use of the commission and bonus funds received from the vendor for the Inmate Welfare Fund.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"10",6,3,null,"Inmates complained that local call costs increased over seven-fold under a new telephone system, while the Sheriff's Department receives commissions and bonuses from the vendor that are not transparently reported.",5,4,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff","Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-78dec397fd",69,"cgj","BOS",5,11,null,"The Board of Supervisors should enact legislation similar to California Senate Bill 1978 regulating the award of the jail telephone service contract for the county jails.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"11",7,3,null,"Unlike proposed state legislation for state prisons, there is no county-level requirement ensuring jail telephone contracts minimize costs to inmates rather than maximize commission revenue to the department.",10,1,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors","Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-9ff59f6b11",69,"cgj","SHF",5,14,null,"The Sheriff's Department should address these complaints to see if the food service can be improved and hot water provided.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"12",8,3,null,"Inmates complained the amount of food served is inadequate, often cold, and there is no hot water for commissary items.",13,null,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-ae4f2f343b",69,"cgj","MYR",5,14,null,"The Sheriff's Department should look into contracting out laundry service and ending the use of inmates to do the laundry in order to ensure a regular, dependable schedule for the exchange of laundered clothing and bedding.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"13",9,3,null,"Inmates do not receive clean clothes even once a week due to broken laundry equipment and low output from inmate work-detail laundry staff.",13,1,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],null,null,null,null,{"text":0.85,"department":0.85,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-49872c7b6b",69,"cgj","MYR",5,1,null,"The Sheriff's Department and the Board of Supervisors should also look into the contract bidding process to see if it can be amended to allow for consideration of other factors besides bid price, such as the quality of clothing and customer support provided.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"14",9,3,null,"The lowest-bid clothing contract resulted in cheap, poorly-made clothing that wore out quickly, causing shortages when the supplier went out of business.",2,null,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],null,null,null,null,{"text":0.85,"department":0.85,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-21f8aeef58",69,"cgj","MYR",5,3,null,"A stockpile of extra clothing and bedding should be maintained for use in times of increased populations in the jails.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"15",9,3,null,"Shortages of inmate clothing have occurred, exacerbated when suppliers go out of business, with no reserve stock available.",0,null,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],null,null,null,null,{"text":0.85,"department":0.85,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-00b2acbeaa",69,"cgj","MYR",5,7,null,"If, as the Sheriff's Department reports, there is a staffing shortage in the jails, additional resources should be dedicated to the Sheriff's Department in order for the department to hire qualified applicants and retain existing staff.",null,"none",null,5,null,null,null,null,null,4900000,{"score":4,"why":null},"16",10,3,null,"A shortage of deputies has led to mandatory overtime and large overtime and workers' compensation expenditures, exceeding the department's budget.",14,4,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],0,9,null,null,{"text":0.85,"department":0.85,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-6f54df5283",69,"cgj","MYR",5,7,null,"The Sheriff's Department should consider the substitution of security guards for deputies wherever appropriate.",null,"none",null,5,null,null,null,null,null,4900000,{"score":4,"why":null},"17",10,3,null,"The Sheriff's Department faces staffing shortages and increased duties, including 24-hour City Hall security, straining deputy resources.",14,null,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],0,9,null,null,{"text":0.85,"department":0.85,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-0992f33d4c",69,"cgj","CAT",5,5,null,"Claims against the City should be reassigned by the City Attorney to either the Police or Health Department after the Sheriff determines the claim was incorrectly filed against his department. The reassignment should commence a new statute of limitations.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"18",14,3,null,"Some inmates file lost-property claims against the Sheriff's Department when arresting officers (Police) or Jail Medical Services (Health) were actually responsible for the property.",5,0,null,null,null,null,null,7,null,null,null,null,null,3,["City Attorney","Sheriff"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-d8c98c5233",69,"cgj","BOS",5,4,null,"In those instances when a claim is for commissary items, the Sheriff's Department should, after verifying the purchase, generally reimburse the inmates with in-kind products. This procedure would short-circuit the costlier, full-blown investigatory claim process, which involves a host of personnel from the offices of the Sheriff, the Controller, and the City Attorney.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"19",15,3,null,"Inmate claims for lost commissary items require costly investigations involving multiple offices, and claims are often denied without outside corroboration.",4,5,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors","Sheriff","City Attorney"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-d0276f56a8",69,"cgj","BOS",5,3,null,"Should space become available at the Hall of Justice, consideration should be given to allow the Property Room to use extra space so that any overflow of property can be better tracked and safeguarded. Consideration should also be given to bringing in experts to evaluate the Property Room to insure optimum use of available space.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"20",15,3,null,"The Property Room at County Jail #9, though newly built, already has insufficient space, causing overflow storage issues for inmate property.",0,null,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors","Sheriff","City Attorney"],null,null,null,null,{"text":0.85,"department":0.85,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-89ca40413f",69,"cgj","SHF",5,5,null,"The camera surveillance area should be expanded to cover the Property Intake window, thereby reducing opportunities for arbitrary and punitive behavior, which could be meted out by the constantly rotating staff. Consideration might also be given to conducting an occasional internal sting operation.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"21",15,3,null,"Lack of camera coverage at the Property Intake window creates opportunities for arbitrary or punitive staff behavior toward inmates.",5,8,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.85,"department":0.9,"category":0.65,"response":0.9,"target_date":0.95},null,[]],["K-3bf1e85c0f",69,"cgj","SHF",5,5,null,"The Operations Manual should be reviewed, corrected, and revised. Among the many changes should be the elimination of the requirement that all women must have their property inventoried, a requirement not applied to male inmates. Beyond this, there should be a new section incorporating the issues and disposition of property not returned to the proper owner. Proper procedures for cash handling...",806,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"22",16,3,null,"The Property Room Operations Manual contains errors, lacks guidance on unclaimed property disposition, imposes an unjustified inventory requirement on women, and prior manual versions are not retained.",5,4,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff","Status of Women","Board of Supervisors"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-c5a5c82864",69,"cgj","SHF",5,5,null,"The Ombudsman should make weekly rounds to each jail and personally hand out and receive grievance forms from inmates.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"23",19,3,null,"Inmates must ask deputies for grievance forms and rely on deputies to deliver completed forms, creating potential for suppression of grievances and delivery delays.",5,14,null,null,null,null,null,7,null,null,null,null,null,3,["Sheriff"],null,null,null,null,{"text":0.9,"department":0.95,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-c0982f18d9",69,"cgj","MYR",5,5,null,"A review of the Grievance Procedure, including the appointment of the Ombudsman by the Sheriff, should be conducted, with serious consideration given to the idea of creating an independent watchdog agency similar to the Police Department OCC, which investigates complaints against the police, or reinstating the Advisory Committee on Adult Detention to administer the grievance process.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"24",20,3,null,"The Ombudsman, appointed by and reporting to the Sheriff, has little independent authority to resolve inmate grievances, particularly those alleging staff misconduct, undermining protection of inmate rights.",5,2,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Board of Supervisors","Sheriff"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-8bb20d7cfe",74,"cgj","BOS",5,5,null,"The Board of Supervisors should formally convey to the Office of the SFFVAC the duties of the SFFVAC as required by SF Administrative Code Sec. 57.10.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1",13,3,null,"SFFVAC disputes that it is responsible under Admin Code Sec. 57.10 for providing the Board of Supervisors an annual accounting of the Film Production Special Fund.",5,0,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-3b01963310",74,"cgj","ADM",5,4,null,"The Office of the SFFVAC should be brought into compliance with SF Administrative Code Sec 57.10 and present the Board of Supervisors with the required annual accounting of the Film Production Special Fund.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"2",13,3,null,"SFFVAC has never compiled or submitted the required annual accounting of the Film Production Special Fund to the Board of Supervisors.",4,0,null,null,null,null,null,7,null,null,null,null,null,3,["Film Commission","Mayor's Office","Board of Supervisors"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-9f3477d626",74,"cgj","ADM",5,8,null,"It is vital, from a management standpoint that the Office of SFFVAC abandon the cardboard box data collection system exhibited to the CGJ. Whether in the form of dedicated software or the use of available retail office management software, the Office of the SFFVAC must institute a system for the collection of the various pertinent data generated by film-work within San Francisco.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",13,3,null,"SFFVAC maintains no database and is unable to effectively review or manage information generated by film-work, hindering oversight.",7,5,null,null,null,null,null,7,null,null,null,null,null,3,["Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.9,"response":0.9,"target_date":0.95},null,[]],["K-dc3713435c",74,"cgj","MYR",5,11,null,"The Office of the SFFVAC should be instructed by the Mayor and the Commission to institute a concise series of procedures along the lines of those instituted by the film offices of other cities heavily utilized by film-makers to actively promote the expansion of the San Francisco Film Industry.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"4",14,3,null,"SFFVAC cannot cite any program or proactive measure taken to fulfill the City's long-term goal of expanding the San Francisco film industry.",10,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-7fa20c13ae",74,"cgj","MYR",5,10,null,"The Office of the SFFVAC should be directed by the Mayor and the Commission to actively collect and analyze data relating to the number of permits issued by the Office of the SFFVAC. The Office of the SFFVAC should be directed to use this information to avoid unfairly impacting the resources of other city agencies. The Office of the SFFVAC should further be directed to take a more proactive...",804,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"5",14,3,null,"SFFVAC does not adequately coordinate permit issuance with other departments (especially PLES/SFPD) and relies too heavily on others to solve problems it creates.",9,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-43e315ee62",74,"cgj","MYR",5,5,null,"It is unacceptable that a department of the City of San Francisco would completely delegate the responsibility assigned it to a privately employed individual over which it could exercise no controls...The Office of the SFFVAC should be sternly admonished by the Mayor and the Commission and instructed to take a more proactive role in the notifications and negotiations provided neighborhoods...",445,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"6",14,3,null,"SFFVAC delegates an unacceptable degree of its 'neighborhood liaison' responsibilities to privately employed location managers with no City oversight.",5,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.9,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-0aea68c06b",74,"cgj","MYR",5,14,null,"The Office of the SFFVAC should be instructed by the Mayor and the Commission to institute a standard notification form to be distributed at all film locations prior to filming including the contact information for both the Office of the SFFVAC and any other participating City department.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"7",15,3,null,"SFFVAC does not use a standard public notification form and requires only location manager contact information, omitting City contact info.",13,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-553a66f292",74,"cgj","MYR",5,14,null,"The Mayor and the Commission should educate the Office of the SFFVAC as to the correlation between the public perception that the Office of the SFFVAC is unresponsive to the needs of the residents and merchants of San Francisco and a lack of public support for film-work in City neighborhoods. Contact information for the Office of the SFFVAC should be present on every document submitted to the...",770,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"8",15,3,null,"SFFVAC has a low public profile; most residents were unaware of it or considered it unresponsive to their concerns.",13,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-cdd27a2a93",74,"cgj","MYR",5,7,null,"The Office of the SFFVAC would greatly benefit from instruction in all aspects of location film production. In addition there is a great need for the SFFVAC to improve both the clerical and communication skills of the Office of the SFFVAC. It is the recommendation of the CGJ that this education be provided to the Office of the SFFVAC.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9a",16,3,null,"The entertainment industry views SFFVAC as naive as to procedures and unskilled in managing location filming.",14,10,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.7,"response":0.9,"target_date":0.95},null,[]],["K-aee7931b50",74,"cgj","MYR",5,7,null,"The CGJ further recommends that the Mayor and the Commission seriously examine the Office of the SFFVAC giving consideration to the inclusion of staff possessing significant practical film production experience. Should budgetary constraints preclude this, replacement of existing staff should be considered.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9b",16,3,null,"SFFVAC lacks staff with practical film production experience, limiting its effectiveness and public dialogue.",14,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.85,"response":0.9,"target_date":0.95},null,[]],["K-91d746acdb",74,"cgj","BOS",5,5,null,"It is the recommendation of the CGJ that the Board of Supervisors revisit the Administrative Code as it pertains to the San Francisco Film and Video Commission. The intent of this recommendation being to correct the lack of required film industry vocational experience among either the Commissioners of the SFFVAC or the Office of SFFVAC staff.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"9c",16,3,null,"There is no requirement that Commissioners or staff have film industry vocational experience, limiting effectiveness.",5,0,null,null,null,null,null,7,null,null,null,null,null,3,["Board of Supervisors"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-ab56b7f4f0",74,"cgj","MYR",5,10,null,"The Office of the SFFVAC should be directed by the Mayor and the Commission to compile and analyze all data relating to neighborhood filming in San Francisco remaining mindful to avoid the excessive approval of film permit requests on any one street or in any one neighborhood.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"10",17,3,null,"SFFVAC fails to provide alternative location/scouting assistance, resulting in excessive use of some neighborhoods by film companies.",9,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-82adaf5f0a",74,"cgj","MYR",5,5,null,"A series of protective procedures such as those in use in Los Angeles, CA and Toronto, Ontario should be negotiated between the Office of the SFFVAC and the various neighborhood associations of San Francisco. These procedures should then be instituted by the Office of the SFFVAC and included in all of their informational materials both printed and electronic.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"11",17,3,null,"SFFVAC has no requirements for neighborhood permission or consensus for impacted areas and delegates public representation to location managers.",5,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-7bd4e47282",74,"cgj","MYR",5,8,null,"The Office of the SFFVAC should be instructed by the Mayor and the Commission to institute a telephone complaint line in order for the public to register their complaints with the SFFVAC. The Office of the SFFVAC should further be instructed by the Mayor and the Commission to document any and all public complaints, whether received by telephone, electronic mail, or written form, in a database...",805,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"12",17,3,null,"SFFVAC does not maintain statistics on complaints and does not record telephone complaints from the public.",7,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-a521e9fa71",74,"cgj","MYR",5,14,null,"The Film Production Guide in use by the Office of the SFFVAC needs to be completely rewritten. The new guide should include standardized examples of the necessary forms complete with contact information for the Office of the SFFVAC, a standardized complaint form, statistics compiled by the Office of the SFFVAC pertaining to economic impact, and employment statistics relating to the San...",754,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"13",18,3,null,"The current Film Production Guide is outdated, inaccurate, superficial, and lacks statistical information of educational use to the public.",13,10,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.75,"response":0.9,"target_date":0.95},null,[]],["K-c3bc5490ac",74,"cgj","MYR",5,8,null,"The Office of the SFFVAC should be instructed by the Mayor and the Commission to include on the SFFVAC website the results of all procedures that are instituted by the Office of the SFFVAC for the collection and dissemination of data. All necessary forms, bearing the contact information for the Office of the SFFVAC should also be made available on-line.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"14",18,3,null,"The SFFVAC website is substandard compared to peer cities' film office websites and fails to provide meaningful educational material.",7,14,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Film Commission"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.9,"target_date":0.95},null,[]],["K-120f94b0d9",67,"cgj","MYR",5,7,null,"Convert the director's position of the OES and the five staff from appointive to competetive civil service positions to ensure continuity in the coordination of emergency services. One solution could be to move the OES from the Mayor's Office to another City department with a civil service infrastructure, such as the Department of Administrative Services.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"1",2,3,null,"OES director and staff positions are mayoral appointments with no legal requirement for expertise, risking political appointees over competent professionals in emergency coordination.",14,5,null,null,null,null,null,7,null,null,null,null,null,3,["Mayor's Office","Human Resources"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.85,"response":0.95,"target_date":0.95},null,[]],["K-9821d8d4c4",67,"cgj","DEM",5,13,null,"Devise a logistical plan to ensure that sufficient fire and police personnel living outside San Francisco can be transported to the City in an emergency.",null,"none",null,5,null,null,null,null,null,null,{"score":3,"why":null},"2",2,3,null,"64 percent of firefighters and 60 percent of police personnel live outside San Francisco, creating delays and logistical problems in emergency response.",12,11,null,null,null,null,null,7,null,null,null,null,null,3,["Emergency Management","Fire Department","Police Department"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.85,"response":0.95,"target_date":0.95},null,[]],["K-8bf0393ac3",67,"cgj","DEM",5,14,null,"Increase the availability of information — via mass media, websites, community organizations, and public schools — on emergency services, NERT training programs, the food and material components of emergency survival kits, and avenues of communication during major emergencies.",null,"none",null,5,null,null,null,null,null,null,{"score":2,"why":null},"3",2,3,null,"Public awareness of emergency services, training programs, and preparedness resources needs improvement.",13,11,null,null,null,null,null,7,null,null,null,null,null,3,["Emergency Management"],null,null,null,null,{"text":0.95,"department":0.9,"category":0.8,"response":0.95,"target_date":0.95},null,[]]]}});
